    ld.global.f32 %f12, [%rd26];
    fma.rn.f32 %f11, %f12, %f12, %f11;
    add.f32 %f10, %f10, %f12;
    // advance to next batch element
    add.u32 %r18, %r18, 1;
    add.s64 %rd24, %rd24, %rd93;    // rd_elem += CHW
    bra LOOP_N_ACCUM;
AFTER_N_ACCUM:
    // Next spatial t
    add.u32 %r17, %r17, %r12;
    bra LOOP_ACCUM;
LOOP_ACCUM_END:
    // Write partial sums to shared memory
    mov.u64 %rd70, sh_sum;
    mul.wide.u32 %rd71, %r10, 4;
    add.s64 %rd72, %rd70, %rd71;
    st.shared.f32 [%rd72], %f10;
    mov.u64 %rd73, sh_sumsq;
    add.s64 %rd74, %rd73, %rd71;
    st.shared.f32 [%rd74], %f11;
