    shr.u32 %r20, %r12, 1;
REDUCE_LOOP:
    setp.eq.u32 %p2, %r20, 0;
    @%p2 bra REDUCE_DONE;
    setp.lt.u32 %p3, %r10, %r20;
    @!%p3 bra SKIP_REDUCE;
    // sh_sum[tid] += sh_sum[tid+stride]
    mov.u64 %rd75, sh_sum;
    mul.wide.u32 %rd76, %r10, 4;
    add.s64 %rd77, %rd75, %rd76;
    add.u32 %r21, %r10, %r20;
    mul.wide.u32 %rd78, %r21, 4;
    add.s64 %rd79, %rd75, %rd78;
    ld.shared.f32 %f20, [%rd77];
    ld.shared.f32 %f21, [%rd79];
    add.f32 %f20, %f20, %f21;
    st.shared.f32 [%rd77], %f20;
    // sh_sumsq[tid] += sh_sumsq[tid+stride]
    mov.u64 %rd80, sh_sumsq;
    mul.wide.u32 %rd81, %r10, 4;
    add.s64 %rd82, %rd80, %rd81;
    add.u32 %r22, %r10, %r20;
    mul.wide.u32 %rd83, %r22, 4;
    add.s64 %rd84, %rd80, %rd83;
    ld.shared.f32 %f22, [%rd82];
    ld.shared.f32 %f23, [%rd84];
    add.f32 %f22, %f22, %f23;
    st.shared.f32 [%rd82], %f22;
SKIP_REDUCE:
